    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        Dues.Basis basis = dues.live(sheetId);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            List<Claim> counting = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(claim -> person.countsLive(claim.getStatus(), claim.getDate(), claim.isStated(), claim.isDeferredOn(today), today))
                    .toList();
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean figured = false;
            for (Claim claim : counting) {
                claimed = claimed.add(claim.getAmount());
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = dues.due(claim, grade, basis);
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                    if (overdue(claim, sheet, grade)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
            // figure (a fixed one, or one at the grade in force on its own date).
            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
            if (!rated && !figured) {
                due = null;
            }
            // A due-total is at most the sheet's cap.
            if (sheet != null) {
                due = sheet.capped(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed, due, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueFigures.add(due);
            }
            overdueFigures.add(overdue);
        }
        return new Rollup(figures, claimedTotal, trimmed(dueFigures), trimmed(overdueFigures));
    }
  /** A person's claims that count in the live totals (see countsLive). */
  private countingOf(personId: number): ClaimView[] {
    const person = this.people().find((p) => p.id === personId);
    return person ? this.claimsOf(personId).filter((c) => countsLive(c, person, this.today())) : [];
  }

  /** What a person has claimed: the sum of their OPEN and SETTLED claims' amounts (see countsLive). */
  protected claimed(personId: number): string {
    return money(this.claimedCents(personId));
  }

  private claimedCents(personId: number): number {
    return this.countingOf(personId).reduce((sum, c) => sum + cents(c.amount), 0);
  }

  /** Whether a person is active on the sheet's today (see activeOn). */
  protected activeOf(person: PersonView): boolean {
    return activeOn(this.claimsOf(person.id), person, this.today());
  }

  /** A person's overdue claims that count in the live totals (see countsLive), each past its grace. */
  protected overdueOf(personId: number): ClaimView[] {
    const person = this.people().find((p) => p.id === personId);
    return person ? this.countingOf(personId).filter((c) => overdue(c, this.today(), this.graceOf(c, person))) : [];
  }

  /** The grace days of a claim: those the grade its person has in force on its date has in force then. */
  private graceOf(claim: ClaimView, person: PersonView): number {
    return graceOn(this.session.graceHistory(), gradeOn(person.grades, claim.date), claim.date);
  }

